/**
 * Check feature availability in the given user mode (base, beta, alpha, etc.)
 * @param {string} userMode - The user mode to check feature availability for.
 * @returns {boolean} - True if the feature is available in the given user mode, false otherwise.
 */
function checkFeatureAvailability(userMode) {
    // Implementation to check feature availability based on user mode
    // Example:
    const featureAvailability = {
        base: ['feature1', 'feature2'],
        beta: ['feature1', 'feature2', 'feature3'],
        alpha: ['feature1', 'feature2', 'feature3', 'feature4']
    };

    return featureAvailability[userMode] ? featureAvailability[userMode].includes('desiredFeature') : false;
}
