/**
 * Temporary class to provide a bridge between old stable mode handling and new Feature management
 * system.
 *
 * Beta mode will be refactored properly in T212802, for now we need an easy way to retrieve
 * information about beta mode.
 *
 * IMPORTANT: This class provides read-only state, if you want to enable/disable beta mode
 * please use MobileContext classes
 *
 */
class BetaModeBridge {
  constructor() {
    this.isBetaModeEnabled = false;
  }

  /**
   * Retrieves the current state of beta mode.
   * @returns {boolean} - True if beta mode is enabled, false otherwise.
   */
  getBetaModeStatus() {
    return this.isBetaModeEnabled;
  }

  /**
   * Sets the state of beta mode.
   * @param {boolean} status - The new status of beta mode.
   */
  setBetaModeStatus(status) {
    this.isBetaModeEnabled = status;
  }
}

export default BetaModeBridge;
